#!/usr/bin/env bash
set -euo pipefail
umask 077
mode="${1:-on}"
case "$mode" in on|off|status) ;; *) echo 'Usage: sudo bash mrsaal-maintenance.sh on|off|status' >&2; exit 1;; esac
app="$(docker ps --filter name=lze8r5qbmjkxshreworyhtb8 --format '{{.Names}}' | head -n 1)"
[[ "$app" =~ ^lze8r5qbmjkxshreworyhtb8-[0-9]{8}T[0-9]{6}$ ]] || { echo 'Mrsaal application container not found.' >&2; exit 1; }
if [[ "$mode" == on ]]; then
 backup_dir="/home/ubuntu/mrsaal-maintenance-backups/$(date +%Y%m%d-%H%M%S)"
 install -d -m 700 "$backup_dir"
 docker cp "$app:/app/routes/site.js" "$backup_dir/site.js.original"
 python3 - "$backup_dir" <<'PYTHON'
from pathlib import Path
import base64,sys
folder=Path(sys.argv[1])
source=(folder/'site.js.original').read_text()
needle=" res.set({'Cache-Control':'no-store','X-Robots-Tag':'noindex'});\n if(!req.session?.userId)return res.redirect('/'+uiLang(req)+'/login');"
replacement=" res.set({'Cache-Control':'no-store','X-Robots-Tag':'noindex'});\n const maintenance=await get('SELECT tool_paused FROM website_settings WHERE id=1');\n if(maintenance?.tool_paused&&(!req.session?.userId||!await isAdmin(req.session.userId))){res.set('Retry-After','300');return res.status(503).sendFile(path.join(publicDir,'maintenance.html'));}\n if(!req.session?.userId)return res.redirect('/'+uiLang(req)+'/login');"
if "const maintenance=await get('SELECT tool_paused FROM website_settings WHERE id=1');" not in source:
    if source.count(needle)!=1: raise SystemExit('Unexpected route file; no application changes made.')
    source=source.replace(needle,replacement,1)
(folder/'site.js').write_text(source)
(folder/'maintenance.html').write_bytes(base64.b64decode(''))
(folder/'maintenance.js').write_bytes(base64.b64decode(''))
for name in ['site.js','maintenance.html','maintenance.js']: (folder/name).chmod(0o644)
PYTHON
 docker cp "$backup_dir/maintenance.html" "$app:/app/public/maintenance.html"
 docker cp "$backup_dir/maintenance.js" "$app:/app/public/assets/maintenance.js"
 # Validate staged route before replacing the running application's file.
 docker cp "$backup_dir/site.js" "$app:/tmp/mrsaal-maintenance-site.js"
 docker exec "$app" node --check /tmp/mrsaal-maintenance-site.js
 docker cp "$backup_dir/site.js" "$app:/app/routes/site.js"
 echo "Maintenance page installed. Original route backup: $backup_dir"
fi
# Existing server-side pause also prevents new non-admin scheduled/campaign sends.
docker exec -i -e MRSAAL_MAINTENANCE_ACTION="$mode" -w /app "$app" node <<'NODE'
(async()=>{
 const {pool}=require('./utils/db');
 try {
  const mode=process.env.MRSAAL_MAINTENANCE_ACTION;
  const result=mode==='status'?await pool.query('SELECT tool_paused FROM website_settings WHERE id=1'):await pool.query('UPDATE website_settings SET tool_paused=$1 WHERE id=1 RETURNING tool_paused',[mode==='on']);
  if(result.rows.length!==1)throw new Error('SETTINGS_MISSING');
  console.log('Maintenance:',result.rows[0].tool_paused?'ON':'OFF');
 }catch(e){console.error('Maintenance update failed:',e.code||'CHECK_SETTINGS');process.exitCode=1;}
 finally{await pool.end();}
})();
NODE
if [[ "$mode" == on ]]; then
 # Restart only the application to load the route patch; no image build or database restart.
 docker restart --time 20 "$app"
 echo 'Open /app in a private browser window to verify the maintenance page.'
 echo 'WhatsApp has NOT been stopped. Stop it only after verifying the page.'
fi
